{"draft":{"version":"a0","html":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pop the Bubbles</title>
<style>
  html, body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background: #f4ecd8;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
  }
  #wrap {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100dvh;
  }
  canvas {
    display: block;
    touch-action: none;
  }
  #clearBtn {
    position: absolute;
    top: 14px;
    right: 14px;
    min-width: 96px;
    min-height: 48px;
    padding: 8px 18px;
    background: #3d405b;
    color: #f4ecd8;
    border: none;
    border-radius: 12px;
    font-size: 16px;
    font-weight: 700;
    box-shadow: 2px 4px 6px rgba(0,0,0,0.25);
    cursor: pointer;
    z-index: 10;
  }
  #clearBtn:active {
    transform: translateY(1px);
  }
  #tallyPlate {
    position: absolute;
    top: 14px;
    left: 14px;
    min-height: 48px;
    padding: 8px 18px;
    background: #e07a5f;
    color: #3d405b;
    border-radius: 12px;
    font-size: 18px;
    font-weight: 800;
    box-shadow: 2px 4px 6px rgba(0,0,0,0.25);
    z-index: 10;
    display: flex;
    align-items: center;
  }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="game"></canvas>
  <div id="tallyPlate">Pops: 0</div>
  <button id="clearBtn">Clear</button>
</div>
<script>
  const CARTRIDGE = {
    send(type, payload = {}) {
      window.parent.postMessage(
        { source: "cartridge", v: 1, type, payload },
        "*",
      );
    },
  };
</script>
<script>
(function () {
  const canvas = document.getElementById("game");
  const ctx = canvas.getContext("2d");
  const clearBtn = document.getElementById("clearBtn");
  const tallyPlate = document.getElementById("tallyPlate");

  let dpr = Math.max(1, window.devicePixelRatio || 1);
  let W = window.innerWidth, H = window.innerHeight;

  function resize() {
    W = window.innerWidth;
    H = window.innerHeight;
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    canvas.style.width = W + "px";
    canvas.style.height = H + "px";
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  resize();

  const PALETTE = {
    bg: "#f4ecd8",
    layer: "#e07a5f",
    accent: "#3d405b",
    highlight: "#81b29a"
  };

  const bubbleColors = [PALETTE.layer, PALETTE.highlight, PALETTE.accent];

  // seeded jitter helper
  function seededRand(seed) {
    let s = seed;
    return function () {
      s = (s * 9301 + 49297) % 233280;
      return s / 233280;
    };
  }

  let paused = false;
  let running = false;
  let tally = 0;
  const bubbles = [];
  const pops = []; // pop animations

  let bubbleIdCounter = 1;

  function spawnBubble() {
    const r = 26 + Math.random() * 30;
    const x = r + Math.random() * (W - 2 * r);
    const y = H + r + Math.random() * 100;
    const speed = 0.4 + Math.random() * 0.6;
    const colorIdx = Math.floor(Math.random() * bubbleColors.length);
    const rnd = seededRand(Math.floor(Math.random() * 100000));
    const jitter = [];
    for (let i = 0; i < 10; i++) {
      jitter.push((rnd() - 0.5) * 3);
    }
    bubbles.push({
      id: bubbleIdCounter++,
      x, y, r,
      speed,
      color: bubbleColors[colorIdx],
      wobblePhase: Math.random() * Math.PI * 2,
      jitter
    });
  }

  function maintainBubbles() {
    const target = Math.min(10, 4 + Math.floor(tally / 5));
    while (bubbles.length < target) {
      spawnBubble();
    }
  }

  let lastSpawnTime = 0;

  function settle(dtSeconds) {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      b.y -= b.speed;
      b.wobblePhase += 0.02;
      if (b.y < -b.r - 50) {
        bubbles.splice(i, 1);
      }
    }
    lastSpawnTime += dtSeconds;
    if (lastSpawnTime > 0.5) {
      lastSpawnTime = 0;
      maintainBubbles();
    }
    for (let i = pops.length - 1; i >= 0; i--) {
      pops[i].life -= dtSeconds;
      if (pops[i].life <= 0) pops.splice(i, 1);
    }
  }

  function popBubbleAt(index) {
    const b = bubbles[index];
    pops.push({ x: b.x, y: b.y, r: b.r, color: b.color, life: 0.35, maxLife: 0.35 });
    bubbles.splice(index, 1);
    tally += 1;
    tallyPlate.textContent = "Pops: " + tally;
    CARTRIDGE.send("score", { value: tally });
  }

  function hitTest(px, py) {
    for (let i = bubbles.length - 1; i >= 0; i--) {
      const b = bubbles[i];
      const dx = px - b.x, dy = py - b.y;
      if (dx * dx + dy * dy <= b.r * b.r) {
        return i;
      }
    }
    return -1;
  }

  function drawRoundedBubble(b) {
    const wob = Math.sin(b.wobblePhase) * 2;
    ctx.save();
    ctx.shadowColor = "rgba(61,64,91,0.35)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetY = 3;
    ctx.beginPath();
    const points = 10;
    for (let i = 0; i < points; i++) {
      const angle = (i / points) * Math.PI * 2;
      const jitterAmt = b.jitter[i];
      const rr = b.r + jitterAmt;
      const px = b.x + Math.cos(angle) * rr + wob * 0.2;
      const py = b.y + Math.sin(angle) * rr;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = b.color;
    ctx.fill();
    ctx.restore();

    // inner highlight card
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.beginPath();
    ctx.ellipse(b.x - b.r * 0.3, b.y - b.r * 0.35, b.r * 0.28, b.r * 0.18, -0.5, 0, Math.PI * 2);
    ctx.fillStyle = "#f4ecd8";
    ctx.fill();
    ctx.restore();
  }

  function drawPop(p) {
    const t = 1 - p.life / p.maxLife;
    const rad = p.r * (1 + t * 0.8);
    ctx.save();
    ctx.globalAlpha = 1 - t;
    ctx.beginPath();
    const points = 8;
    for (let i = 0; i < points; i++) {
      const angle = (i / points) * Math.PI * 2;
      const rr = rad * (0.6 + 0.4 * Math.sin(i * 3 + t * 6));
      const px = p.x + Math.cos(angle) * rr;
      const py = p.y + Math.sin(angle) * rr;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = p.color;
    ctx.fill();
    ctx.restore();
  }

  let hintPhase = 0;

  function draw() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = PALETTE.bg;
    ctx.fillRect(0, 0, W, H);

    // subtle layered background strips
    ctx.save();
    ctx.globalAlpha = 0.5;
    ctx.fillStyle = PALETTE.highlight;
    ctx.beginPath();
    ctx.roundRect ? ctx.roundRect(0, H - 40, W, 40, 10) : ctx.rect(0, H - 40, W, 40);
    ctx.fill();
    ctx.restore();

    for (const b of bubbles) drawRoundedBubble(b);
    for (const p of pops) drawPop(p);

    if (!running) {
      hintPhase += 0.05;
      const alpha = 0.6 + Math.sin(hintPhase) * 0.4;
      ctx.save();
      ctx.globalAlpha = Math.max(0.2, alpha);
      ctx.fillStyle = PALETTE.accent;
      ctx.font = "bold 28px sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("Tap to begin", W / 2, H / 2);
      ctx.restore();
    }
  }

  let lastFrameTime = performance.now();

  function frame() {
    const now = performance.now();
    const dt = Math.min(0.05, (now - lastFrameTime) / 1000);
    lastFrameTime = now;
    if (!paused && running) {
      settle(dt);
    }
    draw();
    requestAnimationFrame(frame);
  }

  function clearTable() {
    bubbles.length = 0;
    pops.length = 0;
    tally = 0;
    tallyPlate.textContent = "Pops: 0";
    CARTRIDGE.send("score", { value: 0 });
    draw();
  }

  function backToTitle() {
    running = false;
    clearTable();
  }

  clearBtn.addEventListener("click", clearTable);

  canvas.style.touchAction = "none";
  canvas.addEventListener("pointerdown", (event) => {
    event.preventDefault();
    if (paused) return;
    const rect = canvas.getBoundingClientRect();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;
    if (!running) {
      running = true;
      CARTRIDGE.send("start");
      maintainBubbles();
      return;
    }
    const idx = hitTest(px, py);
    if (idx >= 0) {
      popBubbleAt(idx);
    }
  });

  window.addEventListener("message", (event) => {
    const data = event.data;
    if (!data || data.source !== "cartridge-host") return;
    if (data.type === "pause") paused = true;
    if (data.type === "resume") paused = false;
    if (data.type === "reset") backToTitle();
  });

  // initial draw + boot
  draw();
  CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });

  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
"}}

